import{_ as l,E as h,o as a,c,b as s,w as e,a as r,I as n,a5 as i,j as t,a4 as d}from"./chunks/framework.B8fOKDsD.js";const T=JSON.parse('{"title":"3 · Observability: What to Measure","description":"A dashboard that diagnoses, DCGM counters, Nsight profiling, and the instrument-reach clinic.","frontmatter":{"title":"3 · Observability: What to Measure","description":"A dashboard that diagnoses, DCGM counters, Nsight profiling, and the instrument-reach clinic.","lastUpdated":true,"prev":{"text":"← 2 · The two walls","link":"/Learning/Inference Optimization/02-two-walls"},"next":{"text":"4 · Batching & scheduling →","link":"/Learning/Inference Optimization/04-batching-scheduling"}},"headers":[],"relativePath":"Learning/Inference Optimization/03-observability.md","filePath":"Learning/Inference Optimization/03-observability.md","lastUpdated":1792901721000}'),u={name:"Learning/Inference Optimization/03-observability.md"},g=t("h1",{id:"🔭-chapter-3-—-observability-what-to-measure",tabindex:"-1"},[r("🔭 Chapter 3 — Observability: What to Measure "),t("a",{class:"header-anchor",href:"#🔭-chapter-3-—-observability-what-to-measure","aria-label":'Permalink to "🔭 Chapter 3 — Observability: What to Measure"'},"​")],-1),m=t("p",null,[t("em",null,"Episodes 14 – 16")],-1),p=t("h2",{id:"🪜-the-instrument-ladder-cheapest-first",tabindex:"-1"},[r("🪜 The instrument ladder (cheapest first) "),t("a",{class:"header-anchor",href:"#🪜-the-instrument-ladder-cheapest-first","aria-label":'Permalink to "🪜 The instrument ladder (cheapest first)"'},"​")],-1),b=d('<blockquote><p>Each instrument sees out to a certain distance and then stops, <strong>and it won&#39;t tell you it stopped</strong>. It just answers.</p></blockquote><hr><h2 id="_1-📊-a-dashboard-built-on-four-questions" tabindex="-1">1. 📊 A dashboard built on four questions <a class="header-anchor" href="#_1-📊-a-dashboard-built-on-four-questions" aria-label="Permalink to &quot;1. 📊 A dashboard built on four questions&quot;">​</a></h2><p>Each panel should answer <strong>one question</strong> you&#39;d ask at 2 a.m. Build panels around the questions, not around metric names, because names change between vLLM, SGLang and TRT-LLM versions.</p><h3 id="q1-is-anything-waiting-and-why" tabindex="-1">Q1. Is anything waiting, and why? <a class="header-anchor" href="#q1-is-anything-waiting-and-why" aria-label="Permalink to &quot;Q1. Is anything waiting, and why?&quot;">​</a></h3>',5),f=d('<h3 id="q2-where-did-the-time-go" tabindex="-1">Q2. Where did the time go? <a class="header-anchor" href="#q2-where-did-the-time-go" aria-label="Permalink to &quot;Q2. Where did the time go?&quot;">​</a></h3><p><strong>E2E = queue + prefill + decode.</strong> (TTFT includes the queue.)</p><ul><li>Queue ↑ → capacity (back to Q1)</li><li>Prefill ↑ → longer prompts or batching changed</li><li>Decode ↑ (others flat) → memory bandwidth</li></ul><div class="warning custom-block"><p class="custom-block-title">📉 Histogram percentiles are estimates</p><p>The buckets are coarse and fixed, so a percentile is <strong>interpolated inside a wide bucket</strong>. Fine for trends, <strong>not</strong> for customer SLAs. Measure SLAs at the client.</p></div><h3 id="q3-is-the-server-redoing-work" tabindex="-1">Q3. Is the server redoing work? <a class="header-anchor" href="#q3-is-the-server-redoing-work" aria-label="Permalink to &quot;Q3. Is the server redoing work?&quot;">​</a></h3><ul><li><strong>Preemption counter</strong> rising under steady traffic → admitting more than it can hold, so prompts get paid for twice.</li><li><strong>Prefix cache hit rate</strong>: vLLM gives raw token counters (hits ÷ queries over any window). SGLang gives a <strong>lifetime</strong> rate, which barely moves when efficiency drops today. Window it yourself.</li><li><strong>Eviction age vs reuse gap</strong>: if blocks are evicted faster than the typical reuse gap, the reuse is real and <strong>the cache is too small</strong>. Take that number to whoever owns the budget.</li></ul><h3 id="q4-am-i-filling-the-batch" tabindex="-1">Q4. Am I filling the batch? <a class="header-anchor" href="#q4-am-i-filling-the-batch" aria-label="Permalink to &quot;Q4. Am I filling the batch?&quot;">​</a></h3><ul><li>vLLM: <strong>tokens per engine step</strong> histogram. Read the distribution, not the mean.</li><li>Triton: <code>inference_count ÷ execution_count</code> = average batch size.</li></ul><div class="danger custom-block"><p class="custom-block-title">🫥 A blank panel looks the same as a healthy one</p><p>vLLM renamed the KV-usage gauge and the prefix-cache counters between major versions and removed some outright. <strong>No error, the panel just draws nothing.</strong> Put metric names in <strong>dashboard variables</strong> so a rename is a one-place fix.</p></div><hr><h2 id="_2-🔬-hardware-counters-dcgm" tabindex="-1">2. 🔬 Hardware counters (DCGM) <a class="header-anchor" href="#_2-🔬-hardware-counters-dcgm" aria-label="Permalink to &quot;2. 🔬 Hardware counters (DCGM)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Counter</th><th>Question it answers</th></tr></thead><tbody><tr><td><strong>SM active</strong></td><td>Was the <em>whole card</em> busy? (a job using ⅕ of the SMs reads 20%, where nvidia-smi would show 100%)</td></tr><tr><td><strong>Tensor pipe active</strong></td><td>Are you using the tensor cores you paid for?</td></tr><tr><td><strong>DRAM / memory interface active</strong></td><td>How close are you to the bandwidth limit?</td></tr><tr><td><strong>NVLink bytes</strong></td><td>Are GPUs talking instead of computing?</td></tr></tbody></table><h3 id="the-verdict-card-cross-the-counters" tabindex="-1">The verdict card (cross the counters) <a class="header-anchor" href="#the-verdict-card-cross-the-counters" aria-label="Permalink to &quot;The verdict card (cross the counters)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>SM</th><th>Tensor</th><th>Memory</th><th>NVLink</th><th>Verdict</th></tr></thead><tbody><tr><td>busy</td><td>quiet</td><td><strong>busy</strong></td><td>—</td><td>🧊 Bandwidth-bound (normal for decode)</td></tr><tr><td>busy</td><td><strong>busy</strong></td><td>—</td><td>—</td><td>🔥 Compute-bound (normal for long prefill)</td></tr><tr><td>low</td><td>low</td><td>low</td><td><strong>high</strong></td><td>📡 Communication-bound → check parallelism / link</td></tr><tr><td>low</td><td>low</td><td>low</td><td>low</td><td>❓ Nothing saturated → <strong>go to the profiler</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">🪑 Occupancy ≠ good usage</p><p>Occupancy counts <strong>resident warps</strong> (how full the seats are), not useful work. DCGM: <em>higher occupancy does not necessarily indicate better GPU usage.</em> It helps when you&#39;re memory-bound (it hides latency) but not when you&#39;re compute-bound. Read <strong>tensor-pipe + memory-interface</strong> instead.</p></div><h3 id="🔥-the-cheapest-alert-you-don-t-have-clock-throttle-reasons" tabindex="-1">🔥 The cheapest alert you don&#39;t have: clock throttle reasons <a class="header-anchor" href="#🔥-the-cheapest-alert-you-don-t-have-clock-throttle-reasons" aria-label="Permalink to &quot;🔥 The cheapest alert you don&#39;t have: clock throttle reasons&quot;">​</a></h3><p>Field values: SW power cap · SW thermal slowdown · <strong>HW slowdown</strong> (cuts clocks <strong>≥ 2×</strong>; caused by heat, PSU brake, or fast power cut).</p><blockquote><p>Everything slows down <strong>in proportion</strong>. Batches still form, cache still fills, every ratio looks normal, so there&#39;s no software symptom to find. <strong>Alert on throttle reason ≠ 0</strong>, and add <strong>XID</strong> (GPU fault) and <strong>PCIe replay</strong> counters.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">✅ This afternoon&#39;s job</p><p>The DCGM exporter&#39;s <strong>default metrics file</strong> ships with SM-active and occupancy <strong>commented out</strong>, and the clock-throttle field <strong>isn&#39;t in it at all</strong>. Uncomment them, add the clock + XID fields, restart the exporter.</p></div><p>NVIDIA has renamed these counters (the <em>ratio</em> names are current). Old names are <strong>deprecated aliases</strong> that still work for now.</p><hr><h2 id="_3-⏱️-profiling-with-nsight-systems" tabindex="-1">3. ⏱️ Profiling with Nsight Systems <a class="header-anchor" href="#_3-⏱️-profiling-with-nsight-systems" aria-label="Permalink to &quot;3. ⏱️ Profiling with Nsight Systems&quot;">​</a></h2><p>Counters are averages over a window, so they <strong>lose ordering</strong>. &quot;Memory 40% busy&quot; can mean 40% steady, or 4 s flat-out then 6 s idle. A profiler puts kernels on a <strong>time axis</strong>.</p><p><strong>Two flags that matter:</strong></p><ul><li><code>--cuda-graph-trace=node</code>: vLLM/TRT-LLM capture decode as a CUDA graph, and without this flag the whole step shows up as one opaque block. (Adds significant overhead, so turn it off afterwards.)</li><li>Python <strong>GIL trace</strong>: GIL contention is an easily missed cause of gaps.</li></ul><h3 id="reading-the-gaps" tabindex="-1">Reading the gaps <a class="header-anchor" href="#reading-the-gaps" aria-label="Permalink to &quot;Reading the gaps&quot;">​</a></h3>',26),w=d('<p>⚠️ vLLM: <strong>end users should never enable profiling.</strong> 100 requests of a 70B trace on an H100 take about <strong>10 minutes just to flush</strong>. Nsight Compute replays and serializes kernels, so never point it at a live server. On <strong>Trainium</strong>: <code>neuron-monitor</code> (counters) + Neuron Profiler (traces); a growing scratchpad means spilling off the chip.</p><hr><h2 id="_4-🩺-clinic-every-instrument-is-right-and-none-of-them-helps" tabindex="-1">4. 🩺 Clinic: every instrument is right and none of them helps <a class="header-anchor" href="#_4-🩺-clinic-every-instrument-is-right-and-none-of-them-helps" aria-label="Permalink to &quot;4. 🩺 Clinic: every instrument is right and none of them helps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Symptom</th><th>What&#39;s actually happening</th><th>Fix</th></tr></thead><tbody><tr><td>1</td><td>Dashboard p99 TTFT = <strong>280 ms</strong> (SLO 300), users say it&#39;s slow</td><td>① The vLLM bucket runs <strong>250–500 ms</strong>, so a 250 ms-wide range vs a 20 ms margin. ② The server clock starts at <em>arrival</em>; LB, network and client time are invisible</td><td><strong>Time at the client</strong> and compare with the dashboard for the same window</td></tr><tr><td>2</td><td>Occupancy <strong>~80%</strong>, is the GPU used well?</td><td>Occupancy = seats filled, not work done</td><td>Read tensor-pipe + memory-interface. Both low → profiler</td></tr><tr><td>3</td><td>Profiler clean, traffic unchanged, <strong>½ the tokens/s</strong> of last week</td><td><strong>HW slowdown</strong> clock throttling</td><td>Throttle-reason field; alert on ≠ 0</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">🧠 The rule</p><p>Software bugs make <strong>one number move while the others don&#39;t</strong>. A slow clock drags <strong>everything down together</strong>. If nothing moved relative to anything else, <strong>check the hardware first</strong>.</p></div><p><strong>Order of investigation:</strong> hardware at full speed? → client timing → server metrics (<em>which stage</em>) → counters (<em>which resource</em>) → profiler (<em>why nobody is busy</em>).</p>',6);function y(k,v,_,C,E,A){const o=h("Mermaid");return a(),c("div",null,[g,m,p,(a(),s(i,null,{default:e(()=>[n(o,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Z%5B%220%EF%B8%8F%E2%83%A3%20Is%20the%20hardware%20at%20full%20speed%3F%3Cbr%2F%3Eclock-throttle%20reason%20%C2%B7%20XID%20%C2%B7%20PCIe%20retries%3Cbr%2F%3E%F0%9F%92%B2%20one%20alert%20rule%22%5D%20--%3E%20A%0A%20%20%20%20A%5B%221%EF%B8%8F%E2%83%A3%20Client-side%20timing%3Cbr%2F%3Ewhat%20the%20user%20actually%20got%3Cbr%2F%3E%F0%9F%92%B2%20one%20real%20request%22%5D%20--%3E%20B%0A%20%20%20%20B%5B%222%EF%B8%8F%E2%83%A3%20Server%20metrics%20(%2Fmetrics)%3Cbr%2F%3EWHICH%20STAGE%3Cbr%2F%3E%F0%9F%92%B2%20free%2C%20already%20running%22%5D%20--%3E%20C%0A%20%20%20%20C%5B%223%EF%B8%8F%E2%83%A3%20Hardware%20counters%20(DCGM)%3Cbr%2F%3EWHICH%20RESOURCE%3Cbr%2F%3E%F0%9F%92%B2%20free%2C%20often%20switched%20off%22%5D%20--%3E%20D%0A%20%20%20%20D%5B%224%EF%B8%8F%E2%83%A3%20Profiler%20(Nsight%20Systems)%3Cbr%2F%3EWHY%20nothing%20is%20busy%3Cbr%2F%3E%F0%9F%92%B2%20slows%20server%2C%20~10%20min%20flush%22%5D%20--%3E%20E%0A%20%20%20%20E%5B%225%EF%B8%8F%E2%83%A3%20Kernel%20profiler%20(Nsight%20Compute)%3Cbr%2F%3Einside%20one%20kernel%3Cbr%2F%3E%F0%9F%92%B2%20take%20the%20job%20out%20of%20production%22%5D%0A"})]),fallback:e(()=>[r(" Loading... ")]),_:1})),b,(a(),s(i,null,{default:e(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20W%5B%22Waiting%20queue%20grows%3Cbr%2F%3Ewhile%20running%20stays%20flat%22%5D%20--%3E%20R%7B%22Waiting%20reason%3F%22%7D%0A%20%20%20%20R%20--%3E%7C%22deferred%3Cbr%2F%3E(LoRA%20budget%2C%20KV%20transfer)%22%7C%20X%5B%22%F0%9F%9A%AB%20Don't%20resize%20memory%3A%3Cbr%2F%3Eyou're%20not%20short%20of%20memory%22%5D%0A%20%20%20%20R%20--%3E%7C%22capacity%22%7C%20G%7B%22KV%20cache%20usage%20gauge%3F%22%7D%0A%20%20%20%20G%20--%3E%7C%22Near%20100%25%22%7C%20K%5B%22Cache%20full%20%E2%86%92%20give%20cache%3Cbr%2F%3Ea%20bigger%20share%20of%20the%20card%22%5D%0A%20%20%20%20G%20--%3E%7C%22Low%22%7C%20S%5B%22Room%20nobody%20uses%20%E2%86%92%20raise%20the%3Cbr%2F%3Emax-concurrent-requests%20limit%22%5D%0A"})]),fallback:e(()=>[r(" Loading... ")]),_:1})),f,(a(),s(i,null,{default:e(()=>[n(o,{id:"mermaid-287",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20G1%5B%22GPU%20idle%20%2B%20Python%20busy%22%5D%20--%3E%20R1%5B%22Host-bound%3A%3Cbr%2F%3Escheduling%2C%20tokenizing%2C%20sampling%22%5D%0A%20%20%20%20G2%5B%22Tiny%20kernels%20back-to-back%22%5D%20--%3E%20R2%5B%22Launch%20overhead%3Cbr%2F%3E%E2%86%92%20CUDA%20graphs%22%5D%0A%20%20%20%20G3%5B%22Sawtooth%3A%20long%20dense%20block%2C%3Cbr%2F%3Ethen%20sparse%20stretch%22%5D%20--%3E%20R3%5B%22Prefill%20blocking%20decode%3Cbr%2F%3E%E2%86%92%20chunked%20prefill%22%5D%0A"})]),fallback:e(()=>[r(" Loading... ")]),_:1})),w])}const q=l(u,[["render",y]]);export{T as __pageData,q as default};
